import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    // ----- Entry point -------------------------------------------------
    public static void main(String[] args) {
        System.out.println("=== Java Demo Application ===");

        // 1️⃣ Create and manipulate a list of numbers
        List<Integer> numbers = Arrays.asList(12, 5, 8, 21, 3);
        System.out.println("Original list: " + numbers);

        // Sort ascending
        List<Integer> sorted = numbers.stream()
                                      .sorted()
                                      .collect(Collectors.toList());
        System.out.println("Sorted list  : " + sorted);

        // Compute sum using streams
        int sum = numbers.stream().mapToInt(Integer::intValue).sum();
        System.out.println("Sum of numbers: " + sum);

        // 2️⃣ Write the sorted list to a file
        Path outFile = Paths.get("sorted_numbers.txt");
        try {
            Files.write(outFile,
                        sorted.stream()
                              .map(Object::toString)
                              .collect(Collectors.joining(System.lineSeparator()))
                              .getBytes());
            System.out.println("Sorted numbers written to " + outFile.toAbsolutePath());
        } catch (IOException e) {
            System.err.println("Failed to write file: " + e.getMessage());
        }

        // 3️⃣ Read the file back and display its contents
        try {
            List<String> lines = Files.readAllLines(outFile);
            System.out.println("File content:");
            lines.forEach(System.out::println);
        } catch (IOException e) {
            System.err.println("Failed to read file: " + e.getMessage());
        }

        // 4️⃣ Simple utility method demo
        String text = "Hello, Java!";
        System.out.println("Reversed string: " + reverse(text));
    }

    // ----- Helper method ------------------------------------------------
    /**
     * Returns a new string that is the reverse of the input.
     *
     * @param s the string to reverse (null‑safe)
     * @return the reversed string, or an empty string if {@code s} is null
     */
    public static String reverse(String s) {
        if (s == null) return "";
        return new StringBuilder(s).reverse().toString();
    }
}
```

